"""Activity Pydantic schemas — mirror the frontend ``Activity`` types.

``metadata`` maps to the ``metadata_json`` column (a flat object of scalar
values, validated by the type ``dict[str, str | int | float | bool | None]``).
"""
from datetime import datetime

from pydantic import BaseModel, ConfigDict, Field, field_validator

# Types a user may create/delete via the API.
MANUAL_ACTIVITY_TYPES = frozenset({"note", "call", "email", "meeting", "sms", "whatsapp"})
# Types generated by the system — never created/deleted via the API.
SYSTEM_ACTIVITY_TYPES = frozenset({"stage_change", "created", "updated", "task_completed"})


class ActivityCreate(BaseModel):
    model_config = ConfigDict(extra="forbid")

    type: str
    subject: str = Field(min_length=1, max_length=500)
    body: str | None = None
    occurred_at: datetime | None = None
    duration_minutes: int | None = Field(default=None, ge=0)
    contact_id: str | None = None
    opportunity_id: str | None = None
    company_id: str | None = None
    task_id: str | None = None
    metadata: dict[str, str | int | float | bool | None] | None = None

    @field_validator(
        "occurred_at", "contact_id", "opportunity_id", "company_id", "task_id", mode="before"
    )
    @classmethod
    def _coerce_empty(cls, value: object) -> object:
        return None if value == "" else value


class ActivityRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: str
    type: str
    subject: str
    body: str | None = None
    occurred_at: datetime
    duration_minutes: int | None = None
    contact_id: str | None = None
    contact_name: str | None = None
    opportunity_id: str | None = None
    opportunity_name: str | None = None
    company_id: str | None = None
    company_name: str | None = None
    task_id: str | None = None
    user_id: str
    user_name: str | None = None
    metadata: dict[str, str | int | float | bool | None] | None = None
    created_at: datetime
